const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Set HTTP security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// 2. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// 3. Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Rate limit exceeded for this endpoint.',
  },
});
app.use('/api/users', strictLimiter);

// 4. Request body size limiting (prevents payload overflow attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Validates request and returns 400 if validation fails
 * Prevents processing of malformed/malicious input
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn('Validation failed:', {
      ip: req.ip,
      path: req.path,
      errors: errors.array(),
      timestamp: new Date().toISOString(),
    });

    return res.status(400).json({
      error: 'Invalid request parameters',
      details: errors.array(),
    });
  }
  next();
};

/**
 * Sanitizes user IDs to prevent NoSQL/SQL injection and integer overflow
 */
const sanitizeUserId = (id) => {
  const num = parseInt(id, 10);
  if (isNaN(num) || num < 0 || num > Number.MAX_SAFE_INTEGER) {
    throw new Error('Invalid user ID');
  }
  return num;
};

/**
 * Sanitizes and validates email addresses
 */
const isValidEmail = (email) => {
  if (!email || typeof email !== 'string') return false;
  // Basic email pattern - more comprehensive validation might be needed
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  // Also check length to prevent ReDoS
  return email.length <= 254 && emailRegex.test(email);
};

/**
 * Sanitizes string input to prevent XSS
 */
const sanitizeString = (str, maxLength = 100) => {
  if (typeof str !== 'string') return '';
  // Remove potentially dangerous characters
  return str
    .trim()
    .replace(/[<>]/g, '') // Remove < and >
    .slice(0, maxLength);
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Global 404 handler - prevents information leakage through default error pages
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found.',
    status: 404,
  });
});

/**
 * Global error handler - centralizes error handling
 * Prevents stack traces from leaking to clients
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log error details server-side (not to client)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    ip: req.ip,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send generic error response to client
  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : err.message,
    status: statusCode,
    ...(process.env.NODE_ENV === 'development' && { debug: err.message }),
  });
});

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * Returns server status - useful for load balancers/orchestration
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    // Even health checks should have error handling
    res.status(503).json({ 
      status: 'error', 
      timestamp: new Date().toISOString(),
    });
  }
});

/**
 * Get users endpoint with pagination
 * Includes:
 * - Query parameter validation
 * - Input sanitization
 * - Pagination limits (prevents data exfiltration)
 */
app.get(
  '/users',
  [
    // Validate and sanitize pagination parameters
    query('page')
      .optional()
      .isInt({ min: 1, max: 1000 })
      .withMessage('Page must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape() // Prevent XSS
      .isLength({ max: 50 })
      .withMessage('Search term too long'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const page = req.query.page || 1;
      const limit = Math.min(req.query.limit || 10, 100); // Hard cap at 100

      // Validate search term if provided
      let searchTerm = null;
      if (req.query.search) {
        searchTerm = sanitizeString(req.query.search, 50);
      }

      // Sample users data (in production, this would be from a database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter by search term if provided
      let filteredUsers = allUsers;
      if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        filteredUsers = allUsers.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      // Response with metadata (helps clients understand data structure)
      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit),
        },
      });
    } catch (error) {
      // Forward to error handler
      next(error);
    }
  }
);

/**
 * Get user by ID endpoint
 * Includes:
 * - Path parameter validation
 * - ID sanitization
 * - Proper error responses
 */
app.get(
  '/users/:id',
  [
    // Validate ID parameter
    body('id')
      .custom((value) => {
        const num = parseInt(value, 10);
        if (isNaN(num) || num < 1 || num > Number.MAX_SAFE_INTEGER) {
          throw new Error('Invalid user ID');
        }
        return true;
      }),
  ],
  validateRequest,
  (req, res) => {
    try {
      const userId = sanitizeUserId(req.params.id);

      // Sample users lookup
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          message: `No user found with ID: ${userId}`,
        });
      }

      res.json({ data: user });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed. Exiting...');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Export for testing
module.exports = app;

