const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security Middleware
app.use(helmet());

// Trust proxy (configure if behind a reverse proxy)
// app.set('trust proxy', 1);

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Too many requests to this endpoint, please try again later.'
  }
});

// Parse JSON with size limit to prevent payload overflow attacks
app.use(express.json({ limit: '10kb' }));

// Validation middleware helper
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Don't expose detailed validation errors in production
    return res.status(400).json({
      error: 'Invalid request parameters',
      details: process.env.NODE_ENV === 'development' ? errors.array() : undefined
    });
  }
  next();
};

// Sanitize function to prevent XSS
const sanitizeOutput = (data) => {
  if (typeof data === 'string') {
    return data.replace(/[<>]/g, '');
  }
  if (Array.isArray(data)) {
    return data.map(sanitizeOutput);
  }
  if (typeof data === 'object' && data !== null) {
    const sanitized = {};
    for (const key in data) {
      sanitized[key] = sanitizeOutput(data[key]);
    }
    return sanitized;
  }
  return data;
};

// Health check endpoint with sanitized output
app.get('/health', 
  [
    query('verbose').optional().isIn(['true', 'false', '1', '0'])
  ],
  validateRequest,
  (req, res) => {
    try {
      const response = {
        status: 'ok',
        timestamp: new Date().toISOString()
      };

      // Only include verbose info when explicitly requested and valid
      if (req.query.verbose === 'true' || req.query.verbose === '1') {
        response.version = '1.0.0';
        response.environment = process.env.NODE_ENV || 'development';
      }

      res.json(sanitizeOutput(response));
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Users endpoint with validation and additional security
app.get('/users',
  strictLimiter,
  [
    query('id').optional().isInt({ min: 1, max: 1000 }).withMessage('ID must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 50 }).withMessage('Limit must be between 1 and 50'),
    query('sort').optional().isIn(['id', 'name', 'email']).withMessage('Invalid sort field')
  ],
  validateRequest,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      let filteredUsers = [...users];

      // Filter by ID if provided
      if (req.query.id) {
        filteredUsers = filteredUsers.filter(u => u.id === parseInt(req.query.id));
      }

      // Sort if requested
      if (req.query.sort) {
        filteredUsers.sort((a, b) => a[req.query.sort].localeCompare(b[req.query.sort]));
      }

      // Limit results
      if (req.query.limit) {
        filteredUsers = filteredUsers.slice(0, parseInt(req.query.limit));
      }

      // Return 404 if no users found after filtering
      if (filteredUsers.length === 0) {
        return res.status(404).json({ error: 'No users found matching criteria' });
      }

      res.json(sanitizeOutput(filteredUsers));
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose stack traces in production
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal server error' : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle server shutdown gracefully
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
