      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape()
      .isLength({ max: 100 })
      .withMessage('Search term too long (max 100 characters)'),
  ],
  handleValidationErrors,
  strictLimiter,
  async (req, res, next) => {
    try {
      const { limit = 10, offset = 0, search } = req.query;

      // Mock user data (in production, query database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply search filter
      let filteredUsers = allUsers;
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = allUsers.filter(user => 
          user.name.toLowerCase().includes(searchLower)
        );
      }

      // Remove email if not authorized (example of data minimization)
      const API_KEY_SECRET = process.env.API_KEY_SECRET;
      const providedApiKey = req.headers['x-api-key'];

      const users = filteredUsers.map(user => ({
        id: user.id,
        name: user.name,
        // Only include email with valid API key
        ...(providedApiKey === API_KEY_SECRET && { email: user.email }),
