const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// CORS configuration - restrict origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 204,
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for user endpoints
const userLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30, // Stricter limit for user data
  message: { error: 'Too many user requests, please try again later.' },
});

// Body parsing with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Request logging middleware (in production, use proper logging library)
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log(`${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });

  next();
});

// Validation middleware helper
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// Sanitize string input helper
const sanitizeString = (str) => {
  if (typeof str !== 'string') return str;
  return str.trim().replace(/[<>]/g, '');
};

// Health endpoint
app.get('/health', [
  query('format').optional().isIn(['json', 'text']).withMessage('Invalid format parameter'),
  validateRequest,
], (req, res) => {
  try {
    const format = req.query.format || 'json';
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    if (format === 'text') {
      res.set('Content-Type', 'text/plain');
      return res.send('OK');
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error.message);
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint with validation and pagination
app.get('/users', userLimiter, [
  query('page').optional().isInt({ min: 1, max: 1000 }).withMessage('Page must be between 1 and 1000'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('sort').optional().matches(/^(name|email|id):(asc|desc)$/).withMessage('Invalid sort format'),
  query('fields').optional().matches(/^[a-z,]+$/).withMessage('Invalid fields format'),
  validateRequest,
], (req, res) => {
  try {
    // Extract and validate query parameters
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const skip = (page - 1) * limit;

    // Available users data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Limit results (in real app, this would be database query)
    const users = allUsers.slice(skip, skip + limit);

    // Sanitize user data before sending
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: sanitizeString(user.name),
      email: user.email, // In production, consider masking emails
    }));

    const response = {
      data: sanitizedUsers,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        totalPages: Math.ceil(allUsers.length / limit),
      },
    };

    // Apply field filtering if requested
    if (req.query.fields) {
      const fields = req.query.fields.split(',');
      const validFields = ['id', 'name', 'email'];
      const requestedFields = fields.filter(f => validFields.includes(f));

      if (requestedFields.length > 0) {
        response.data = sanitizedUsers.map(user => {
          const filteredUser = {};
          requestedFields.forEach(field => {
            if (user[field] !== undefined) {
              filteredUser[field] = user[field];
            }
          });
          return filteredUser;
        });
      }
    }

    res.json(response);
  } catch (error) {
    console.error('Users endpoint error:', error.message);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// User by ID endpoint
app.get('/users/:id', userLimiter, [
  param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
  validateRequest,
], (req, res) => {
  try {
    const userId = parseInt(req.params.id);

    // Available users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({
      id: user.id,
      name: sanitizeString(user.name),
      email: user.email,
    });
  } catch (error) {
    console.error('User by ID error:', error.message);
    res.status(500).json({ error: 'Failed to retrieve user' });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found', path: req.path });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { 
      message: err.message,
      stack: err.stack 
    }),
  });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

const gracefulShutdown = () => {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown();
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

