app.get('/health', [
  query('format').optional().isIn(['json', 'text'])
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Validation failed' });
  }
  // ... rest of handler
});
```

### Priority 3: Add Security Middleware
Install: `npm install helmet cors express-rate-limit`

```javascript
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

app.use(helmet());
app.use(cors({ origin: process.env.ALLOWED_ORIGINS || ['http://localhost:3000'] }));

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);

app.use(express.json({ limit: '1mb' }));
```

---

## Minimal Implementation

Here's the minimal secure version of app.js with just the essentials:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(express.json({ limit: '1mb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests' }
});
app.use(limiter);

// Validation helper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Invalid input' });
  }
  next();
};

// Health endpoint with validation
app.get('/health', [
  query('format').optional().isIn(['json', 'text']),
  validate
], (req, res) => {
  try {
    const format = req.query.format || 'json';
    if (format === 'text') {
      return res.send('OK');
    }
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error('Health error:', error.message);
    res.status(500).json({ error: 'Server error' });
  }
});

// Users endpoint with rate limiting and error handling
app.get('/users', (req, res) => {
  try {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    console.error('Users error:', error.message);
    res.status(500).json({ error: 'Server error' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

---

## Required npm Packages

```bash
npm install helmet express-rate-limit express-validator
```

Update package.json dependencies:
