# Security Review: app.js

## Current Issues Identified

### 1. Missing Input Validation
- No validation on query parameters or request body
- No sanitization of user inputs
- No rate limiting on endpoints

### 2. Insufficient Error Handling
- No try-catch blocks around route handlers
- No global error handling middleware
- Errors may leak sensitive information in production

### 3. Security Headers Missing
- No Helmet.js for security headers
- Missing CORS configuration
- No Content Security Policy

### 4. Other Security Concerns
- No rate limiting (vulnerable to DoS attacks)
- No request logging for security monitoring
- No HTTPS enforcement
- Sensitive data (emails) exposed without authorization checks
- No input sanitization against XSS
- No protection against injection attacks

---

## Improved Implementation

Below is a security-enhanced version of `app.js` with comprehensive error handling and input validation:

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent payload bombs

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests to this endpoint, please try again later.',
});

// Middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// Global error handling middleware (should be last)
const errorHandler = (err, req, res, next) => {
  // Log error for monitoring (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
};

// 404 handler
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path
  });
};

// Request logging middleware for security monitoring
const requestLogger = (req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log({
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    });
  });

  next();
};

app.use(requestLogger);

// Routes with proper error handling and validation

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    next(error); // Pass to global error handler
  }
});

app.get('/users', 
  strictLimiter,
  [
    // Validate and sanitize query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape() // Prevent XSS
      .isLength({ max: 100 })
      .withMessage('Search term too long'),
    query('fields')
      .optional()
      .trim()
      .custom(value => {
        // Whitelist allowed fields
        const allowedFields = ['id', 'name', 'email'];
        const requestedFields = value.split(',');
        const invalidFields = requestedFields.filter(f => !allowedFields.includes(f));
        if (invalidFields.length > 0) {
          throw new Error(`Invalid fields: ${invalidFields.join(', ')}`);
        }
        return true;
      })
  ],
  handleValidationErrors,
  async (req, res, next) => {
    try {
      // In a real app, you would:
      // 1. Check authentication/authorization
      // 2. Validate that user has permission to view users
      // 3. Sanitize output data

      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters based on validated query parameters
      let users = [...allUsers];

      const { limit = 10, offset = 0, search, fields } = req.query;

      if (search) {
        users = users.filter(user => 
          user.name.toLowerCase().includes(search.toLowerCase()) ||
          user.email.toLowerCase().includes(search.toLowerCase())
        );
      }

      // Field selection (whitelist-based)
      if (fields) {
        const requestedFields = fields.split(',');
        users = users.map(user => {
          const filtered = {};
          requestedFields.forEach(field => {
            if (user[field] !== undefined) {
              filtered[field] = user[field];
            }
          });
          return filtered;
        });
      }

      // Apply pagination
      const paginatedUsers = users.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        meta: {
          total: users.length,
          limit,
          offset,
          hasMore: offset + limit < users.length
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

// Example of a POST endpoint with full validation
app.post('/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .escape()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s\-']+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .normalizeEmail()
      .isEmail()
      .withMessage('Invalid email address')
      .isLength({ max: 255 })
      .withMessage('Email too long'),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150')
  ],
  handleValidationErrors,
  async (req, res, next) => {
    try {
      // In a real app, you would:
      // 1. Check authentication
      // 2. Validate unique constraints
      // 3. Hash sensitive data
      // 4. Save to database with parameterized queries

      const { name, email, age } = req.body;

      // Simulate user creation
      const newUser = {
        id: Date.now(), // In real app, use proper ID generation
        name,
        email,
        ...(age && { age })
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      next(error);
    }
  }
);

// Apply error handlers (must be after all routes)
app.use(notFoundHandler);
app.use(errorHandler);

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle shutdown gracefully
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;
```

