    return req.path === '/health' && process.env.NODE_ENV === 'production';
  }
});

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Too many requests to this endpoint, please try again later.'
  }
});

app.use('/api/', generalLimiter);

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to handle express-validator errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

/**
 * Whitelist validator for field selection
 */
const validateFields = (allowedFields) => {
  return (value) => {
    if (!value) return true;
    const requestedFields = value.split(',').map(f => f.trim());
    const invalidFields = requestedFields.filter(f => !allowedFields.includes(f));
    if (invalidFields.length > 0) {
      throw new Error(`Invalid fields: ${invalidFields.join(', ')}`);
    }
    return true;
  };
};

// ============================================================================
// LOGGING MIDDLEWARE
// ============================================================================

/**
 * Request logging for security monitoring and debugging
 */
const requestLogger = (req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logData = {
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      timestamp: new Date().toISOString()
    };

    // In production, send to proper logging service
    if (res.statusCode >= 400) {
