    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape() // Prevent XSS
      .isLength({ max: 100 })
      .withMessage('Search term too long (max 100 characters)'),
