      .optional()
      .trim()
      .custom(validateFields(['id', 'name', 'email']))
      .withMessage('Invalid field selection')
  ],
  handleValidationErrors,
  async (req, res, next) => {
    try {
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Get validated and parsed query parameters
      const limit = req.query.limit || 10;
      const page = req.query.page || 1;
      const search = req.query.search;
      const fields = req.query.fields;

      let users = [...allUsers];

      // Apply search filter (case-insensitive)
      if (search) {
        const searchLower = search.toLowerCase();
        users = users.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply field selection (security: only return requested fields)
      let responseData = users;
      if (fields) {
        const requestedFields = fields.split(',').map(f => f.trim());
        responseData = users.map(user => {
          const filtered = {};
          requestedFields.forEach(field => {
            if (user[field] !== undefined) {
              filtered[field] = user[field];
            }
          });
          return filtered;
        });
      }

      // Calculate pagination
      const total = responseData.length;
      const totalPages = Math.ceil(total / limit);
      const offset = (page - 1) * limit;
      const paginatedData = responseData.slice(offset, offset + limit);

      res.json({
        data: paginatedData,
        meta: {
          total,
          page,
          limit,
          totalPages,
          hasNextPage: page < totalPages,
          hasPreviousPage: page > 1
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * Create user endpoint with comprehensive validation
 * POST /users
 */
app.post('/users',
  strictLimiter,
  [
