// Improved application with security best practices
// This includes input validation, error handling, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Apply security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// Configure CORS (restrict to specific origins)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 204,
};
app.use(require('cors')(corsOptions));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes',
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Only 10 requests per 15 minutes
  message: {
    error: 'Too many attempts, please try again later',
  },
});

// Body parser with size limits
app.use(express.json({ 
  limit: '10kb', // Limit payload size
  strict: true 
}));

// Request logging for security monitoring
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ==================== INPUT VALIDATION HELPERS ====================

/**
 * Middleware to check validation results
 * If validation fails, returns 400 with error details
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn('Validation failed:', errors.array());
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

/**
 * Sanitize string input to prevent injection attacks
 */
const sanitizeString = (input) => {
  if (typeof input !== 'string') return input;
  // Remove potentially dangerous characters
  return input
    .replace(/[<>]/g, '') // Remove < and > to prevent XSS
    .trim()
    .substring(0, 1000); // Truncate long strings
};

/**
 * Validate and sanitize ID parameter
 */
const validateId = (id) => {
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId < 1 || numId > Number.MAX_SAFE_INTEGER) {
    return null;
  }
  return numId;
};

// ==================== ERROR HANDLING MIDDLEWARE ====================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString(),
  });
});

/**
 * Global error handling middleware
 * Catches all errors and prevents sensitive information leakage
 */
app.use((err, req, res, next) => {
  // Log error details for debugging (in production, use proper logging service)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send safe error response (don't expose internal details in production)
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal Server Error',
    timestamp: new Date().toISOString(),
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Graceful shutdown
  shutdown(err);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown(reason);
});

/**
 * Graceful shutdown function
 */
function shutdown(error) {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(error ? 1 : 0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
}

// ==================== ROUTES ====================

/**
 * @route   GET /health
 * @desc    Health check endpoint
 * @access  Public
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

/**
 * @route   GET /users
 * @desc    Get all users with optional filtering and pagination
 * @access  Public
 * @query   limit - Number of users to return (1-100)
 * @query   offset - Number of users to skip
 */
app.get('/users', [
  // Input validation using express-validator
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
], validateRequest, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply pagination with validated defaults
    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length,
      },
    });
  } catch (error) {
    // This will be caught by the error handling middleware
    next(error);
  }
});

/**
 * @route   GET /users/:id
 * @desc    Get a specific user by ID
 * @access  Public
 * @param   id - User ID (must be a positive integer)
 */
app.get('/users/:id', [
  param('id')
    .custom((value) => {
      const id = validateId(value);
      if (id === null) {
        throw new Error('Invalid user ID');
      }
      return true;
    })
    .withMessage('ID must be a positive integer'),
], validateRequest, (req, res) => {
  try {
    const userId = validateId(req.params.id);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        timestamp: new Date().toISOString(),
      });
    }

    res.json(user);
  } catch (error) {
    next(error);
  }
});

/**
 * @route   POST /users
 * @desc    Create a new user
 * @access  Public (in production, add authentication)
 */
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(), // Escape HTML entities
  body('email')
    .trim()
    .isEmail()
    .withMessage('Must be a valid email address')
    .normalizeEmail(),
], validateRequest, (req, res) => {
  try {
    const { name, email } = req.body;

    // Additional sanitization
    const sanitizedName = sanitizeString(name);

    // In a real application, save to database here
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name: sanitizedName,
      email,
    };

    return res.status(201).json({
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = { app, server };

