/**
 * Example security tests for the improved app.js
 * Run with: npm test
 */

const request = require('supertest');
const app = require('./app');

describe('Security Tests', () => {
  describe('Security Headers', () => {
    test('should set Content-Security-Policy header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['content-security-policy']).toBeDefined();
      expect(response.headers['content-security-policy']).toContain("default-src 'self'");
    });

    test('should set X-Frame-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-frame-options']).toBeDefined();
    });

    test('should set Strict-Transport-Security header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['strict-transport-security']).toBeDefined();
    });

    test('should set X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });
  });

  describe('Rate Limiting', () => {
    test('should include rate limit headers', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-ratelimit-limit']).toBeDefined();
      expect(response.headers['x-ratelimit-remaining']).toBeDefined();
    });
  });

  describe('Request Tracking', () => {
    test('should include X-Request-ID header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-request-id']).toBeDefined();
      expect(response.headers['x-request-id']).toMatch(/^[a-f0-9]{32}$/);
    });

    test('should include requestId in response body', async () => {
      const response = await request(app).get('/health');
      expect(response.body.requestId).toBeDefined();
      expect(response.body.requestId).toBe(response.headers['x-request-id']);
    });
  });

  describe('Input Validation', () => {
    test('should reject invalid limit parameter', async () => {
      const response = await request(app)
        .get('/users?limit=invalid');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Invalid query parameters');
    });

    test('should reject search with special characters', async () => {
      const response = await request(app)
        .get('/users?search=<script>alert(1)</script>');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Invalid query parameters');
    });

    test('should reject search exceeding max length', async () => {
      const response = await request(app)
        .get('/users?search=' + 'a'.repeat(101));
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Invalid query parameters');
    });

    test('should accept valid search parameter', async () => {
      const response = await request(app)
        .get('/users?search=Alice');
      expect(response.status).toBe(200);
      expect(response.body.data).toBeDefined();
    });
  });

  describe('Data Sanitization', () => {
    test('should sanitize user data', async () => {
      // Update test data to include XSS attempts when implemented
      const response = await request(app).get('/users');
      expect(response.status).toBe(200);
      expect(response.body.data).toBeInstanceOf(Array);
    });
  });

  describe('Error Handling', () => {
    test('should return 404 for invalid routes', async () => {
      const response = await request(app).get('/invalid-route');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not found');
      expect(response.body.path).toBe('/invalid-route');
    });
  });

  describe('Health Check', () => {
    test('should return health status', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
      expect(response.body.status).toBe('ok');
      expect(response.body.timestamp).toBeDefined();
    });
  });

  describe('Users Endpoint', () => {
    test('should return users list', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(200);
      expect(response.body.data).toBeInstanceOf(Array);
      expect(response.body.count).toBeGreaterThan(0);
    });

    test('should support pagination', async () => {
      const response = await request(app)
        .get('/users?limit=1&offset=0');
      expect(response.status).toBe(200);
      expect(response.body.data.length).toBeLessThanOrEqual(1);
    });

    test('should support search', async () => {
      const response = await request(app)
        .get('/users?search=Alice');
      expect(response.status).toBe(200);
      expect(response.body.data).toBeInstanceOf(Array);
    });

    test('should limit maximum items per page', async () => {
      const response = await request(app)
        .get('/users?limit=999');
      expect(response.status).toBe(200);
      // Should be capped at 100 or less
      expect(response.body.data.length).toBeLessThanOrEqual(100);
    });
  });
});

describe('Security Tests - Advanced', () => {
  describe('XSS Prevention', () => {
    test('should sanitize HTML in user responses', async () => {
      // This test would be enhanced with test data containing XSS attempts
      const response = await request(app).get('/users');
      const htmlSafe = (str) => !/<script|javascript:|onerror=/i.test(str);

      response.body.data.forEach(user => {
        if (user.name) expect(htmlSafe(user.name)).toBe(true);
        if (user.email) expect(htmlSafe(user.email)).toBe(true);
      });
    });
  });

  describe('Content Security', () => {
    test('should not accept arbitrary Content-Type', async () => {
      const response = await request(app)
        .get('/users')
        .set('Content-Type', 'application/xml');
      // Should still work but with proper handling
      expect(response.status).toBeLessThan(500);
    });
  });

  describe('Information Disclosure', () => {
    test('should not expose stack traces in error responses', async () => {
      const response = await request(app).get('/nonexistent');
      expect(response.status).toBe(404);
      expect(response.body.stack).toBeUndefined();
      expect(response.body.error).toBeDefined();
    });
  });
});

