// Secure application with proper error handling and input validation
// Security-focused implementation following OWASP best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Set security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  xframeOptions: { action: 'deny' },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: '900'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Rate limit exceeded for this endpoint.',
  }
});

// Apply rate limiting
app.use(limiter);

// Body parsing with size limits to prevent buffer overflow attacks
app.use(express.json({ 
  limit: '10kb',
  strict: true 
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

/**
 * Middleware to validate user ID parameter
 */
const validateUserId = [
  param('id')
    .isInt({ min: 1, max: 999999 })
    .withMessage('ID must be a positive integer')
    .toInt(),
  handleValidationErrors
];

/**
 * Middleware to validate query parameters for user listing
 */
const validateUserQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0, max: 10000 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  query('sort')
    .optional()
    .isIn(['id', 'name', 'email', '-id', '-name', '-email'])
    .withMessage('Sort must be a valid field name'),
  handleValidationErrors
];

/**
 * Middleware to validate user creation/update
 */
const validateUserBody = [
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z0-9\s\-'\.]+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
  handleValidationErrors
];

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found Handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

/**
 * Global Error Handler
 */
app.use((err, req, res, next) => {
  // Log error details (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal errors in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Handle specific error types
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Invalid JSON',
      message: 'The request body contains invalid JSON'
    });
  }

  if (err.type === 'entity.too.large') {
    return res.status(413).json({
      error: 'Payload Too Large',
      message: 'Request body exceeds size limit'
    });
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
    timestamp: new Date().toISOString()
  });
});

/**
 * Async route wrapper to catch errors in async handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// SANITIZATION UTILITIES
// ============================================================================

/**
 * Sanitize user data before sending in response
 * Removes sensitive fields and escapes potentially dangerous content
 */
const sanitizeUser = (user) => {
  const sanitized = { ...user };

  // Remove sensitive fields (if any)
  delete sanitized.password;
  delete sanitized.ssn;
  delete sanitized.creditCard;

  // Escape HTML in string fields to prevent XSS
  Object.keys(sanitized).forEach(key => {
    if (typeof sanitized[key] === 'string') {
      sanitized[key] = sanitized[key]
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;');
    }
  });

  return sanitized;
};

/**
 * Validate user object structure
 */
const isValidUser = (user) => {
  return user && 
         typeof user.id === 'number' &&
         typeof user.name === 'string' &&
         typeof user.email === 'string';
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint (no validation needed)
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Get users with pagination and sorting
app.get('/users', validateUserQuery, asyncHandler(async (req, res) => {
  // Get validated and sanitized query parameters
  const limit = req.query.limit || 10;
  const offset = req.query.offset || 0;
  const sort = req.query.sort || 'id';

  // Mock users database
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' },
    { id: 5, name: 'Eve', email: 'eve@example.com' },
  ];

  // Validate all users before processing
  const validUsers = allUsers.filter(isValidUser);

  // Apply sorting
  const [sortField, sortOrder] = sort.startsWith('-') 
    ? [sort.slice(1), -1] 
    : [sort, 1];

  validUsers.sort((a, b) => {
    if (a[sortField] < b[sortField]) return -1 * sortOrder;
    if (a[sortField] > b[sortField]) return 1 * sortOrder;
    return 0;
  });

  // Apply pagination
  const paginatedUsers = validUsers.slice(offset, offset + limit);

  // Sanitize output
  const sanitizedUsers = paginatedUsers.map(sanitizeUser);

  // Return response with metadata
  res.json({
    data: sanitizedUsers,
    meta: {
      total: validUsers.length,
      limit,
      offset,
      hasMore: offset + limit < validUsers.length
    }
  });
}));

// Get single user by ID
app.get('/users/:id', validateUserId, asyncHandler(async (req, res) => {
  const userId = req.params.id;

  // Mock users database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({
      error: 'User not found',
      message: `No user exists with ID ${userId}`
    });
  }

  // Validate and sanitize
  if (!isValidUser(user)) {
    throw new Error('Invalid user data');
  }

  res.json({ data: sanitizeUser(user) });
}));

// Create new user (with strict rate limiting)
app.post('/users', strictLimiter, validateUserBody, asyncHandler(async (req, res) => {
  const { name, email } = req.body;

  // Check for duplicates (mock implementation)
  const existingUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const emailExists = existingUsers.some(u => u.email === email);
  if (emailExists) {
    return res.status(409).json({
      error: 'Conflict',
      message: 'A user with this email already exists'
    });
  }

  // Create new user (in real app, this would be a database operation)
  const newUser = {
    id: Math.max(...existingUsers.map(u => u.id)) + 1,
    name,
    email
  };

  // Validate before sending
  if (!isValidUser(newUser)) {
    throw new Error('Invalid user data created');
  }

  res.status(201).json({ 
    message: 'User created successfully',
    data: sanitizeUser(newUser)
  });
}));

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '127.0.0.1'; // Default to localhost for security

if (require.main === module) {
  app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

