/**
 * CONFIGURATION VALIDATION EXAMPLE
 * 
 * This shows how to properly validate environment variables
 * before the application starts.
 * 
 * Add this to the top of app-improved.js after loading dotenv
 */

// Load environment variables from .env file
require('dotenv').config();

/**
 * Configuration Schema
 * Define all required and optional environment variables
 */
const configSchema = {
  required: {
    NODE_ENV: {
      description: 'Node environment (development, test, production)',
      validate: (value) => ['development', 'test', 'production'].includes(value),
      defaultValue: 'development'
    }
  },
  optional: {
    PORT: {
      description: 'Server port number',
      validate: (value) => {
        const num = parseInt(value, 10);
        return !isNaN(num) && num >= 1 && num <= 65535;
      },
      defaultValue: 3000
    },
    ALLOWED_ORIGINS: {
      description: 'CORS allowed origins (comma-separated)',
      validate: (value) => {
        if (!value) return true;
        const origins = value.split(',');
        return origins.every(origin => {
          try {
            new URL(origin);
            return true;
          } catch {
            return false;
          }
        });
      },
      defaultValue: 'http://localhost:3000'
    },
    RATE_LIMIT_WINDOW_MS: {
      description: 'Rate limit time window in milliseconds',
      validate: (value) => {
        const num = parseInt(value, 10);
        return !isNaN(num) && num > 0;
      },
      defaultValue: 900000
    },
    RATE_LIMIT_MAX_REQUESTS: {
      description: 'Maximum requests per rate limit window',
      validate: (value) => {
        const num = parseInt(value, 10);
        return !isNaN(num) && num > 0;
      },
      defaultValue: 100
    },
    MAX_JSON_BODY_SIZE: {
      description: 'Maximum JSON body size',
      validate: (value) => /\d+[kbmgKBMG]+/.test(value),
      defaultValue: '10kb'
    },
    LOG_LEVEL: {
      description: 'Logging level',
      validate: (value) => ['error', 'warn', 'info', 'debug'].includes(value),
      defaultValue: 'info'
    }
  }
};

/**
 * Validate environment configuration
 * @returns {Object} Validated configuration object
 */
function validateConfig() {
  const config = {};
  const errors = [];
  const warnings = [];

  console.log('🔍 Validating environment configuration...\n');

  // Validate required variables
  for (const [key, schema] of Object.entries(configSchema.required)) {
    const value = process.env[key];

    if (value === undefined || value === null || value === '') {
      if (schema.defaultValue !== undefined) {
        config[key] = schema.defaultValue;
        warnings.push(`⚠️  ${key} not set, using default: ${schema.defaultValue}`);
      } else {
        errors.push(`❌ ${key} is required but not set`);
      }
    } else if (schema.validate && !schema.validate(value)) {
      errors.push(`❌ ${key} has invalid value: ${value} (${schema.description})`);
    } else {
      config[key] = value;
      console.log(`✅ ${key}: ${value}`);
    }
  }

  console.log('');

  // Validate optional variables
  for (const [key, schema] of Object.entries(configSchema.optional)) {
    const value = process.env[key];

    if (value === undefined || value === null || value === '') {
      config[key] = schema.defaultValue;
      console.log(`ℹ️  ${key}: (not set, using default: ${schema.defaultValue})`);
    } else if (schema.validate && !schema.validate(value)) {
      warnings.push(`⚠️  ${key} has invalid value: ${value}, using default: ${schema.defaultValue}`);
      config[key] = schema.defaultValue;
    } else {
      config[key] = value;
      console.log(`✅ ${key}: ${value}`);
    }
  }

  console.log('');

  // Print warnings
  if (warnings.length > 0) {
    console.log('⚠️  Warnings:');
    warnings.forEach(warning => console.log(`  ${warning}`));
    console.log('');
  }

  // Print errors and exit if any
  if (errors.length > 0) {
    console.error('❌ Configuration Errors:');
    errors.forEach(error => console.error(`  ${error}`));
