/**
 * Improved Application with Security Best Practices
 * 
 * Key Security Improvements:
 * 1. Helmet.js for HTTP headers security
 * 2. Rate limiting to prevent DDoS attacks
 * 3. Input validation and sanitization
 * 4. CORS configuration
 * 5. Proper error handling with global error middleware
 * 6. Request size limiting to prevent DoS
 * 7. Security HTTP headers
 * 8. Logging for security events
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const cors = require('cors');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE CONFIGURATION
// ============================================================================

// 1. Helmet.js - Security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  xssFilter: true,
  frameguard: { action: 'deny' }
}));

// 2. Rate Limiting - Prevent DDoS/Brute Force
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: req.rateLimit.resetTime
    });
  }
});

// Stricter rate limiting for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many attempts, please try again later.'
});

app.use(limiter);

// 3. CORS Configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// 4. Request Body Size Limit - Prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Security Logging Middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const ip = req.ip || req.connection.remoteAddress;
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${ip}`);
  next();
});

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Validation Error Handler
 * Centralizes validation error responses
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const sanitizedErrors = errors.array().map(err => ({
      field: err.path || err.param,
      message: err.msg,
      location: err.location
    }));

    return res.status(400).json({
      error: 'Validation failed',
      details: sanitizedErrors
    });
  }
  next();
};

/**
 * Sanitize user input to prevent injection attacks
 */
const sanitizeInput = (value) => {
  if (typeof value !== 'string') return value;
  // Remove potentially dangerous characters
  return value
    .replace(/[<>]/g, '') // Prevent HTML/XML injection
    .trim();
};

// ============================================================================
// ROUTE HANDLERS WITH PROPER ERROR HANDLING
// ============================================================================

/**
 * Health Check Endpoint
 * Returns server status with security headers
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Health check failed'
    });
  }
});

/**
 * Users Endpoint with Pagination and Filtering
 * Includes input validation and security checks
 */
app.get('/users', 
  [
    query('page')
      .optional()
      .isInt({ min: 1, max: 1000 })
      .withMessage('Page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('search')
      .optional()
      .trim()
      .isLength({ max: 100 })
      .withMessage('Search term too long'),
    query('sort')
      .optional()
      .isIn(['name', 'email', 'id'])
      .withMessage('Invalid sort field'),
  ],
  handleValidationErrors,
  async (req, res) => {
    try {
      // Extract and sanitize query parameters
      const page = parseInt(req.query.page) || 1;
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const search = sanitizeInput(req.query.search || '');
      const sort = req.query.sort || 'id';

      // Security: Validate limit to prevent excessive data exposure
      if (limit > 100) {
        return res.status(400).json({
          error: 'Invalid parameter',
          message: 'Limit cannot exceed 100'
        });
      }

      // Sample data (in production, this would come from a database)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Filter users based on search term
      let filteredUsers = allUsers;
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = allUsers.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Sort users
      filteredUsers.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });

      // Pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      // Response with metadata
      res.json({
        data: paginatedUsers,
        meta: {
          page,
          limit,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit)
        }
      });

    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({
        error: 'Internal server error',
        message: 'An error occurred while retrieving users'
      });
    }
  }
);

/**
 * Get User by ID Endpoint
 * Includes path parameter validation
 */
app.get('/users/:id',
  [
    // Validate ID parameter
  ],
  handleValidationErrors,
  async (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Validate ID is a positive integer
      if (!Number.isInteger(userId) || userId < 1) {
        return res.status(400).json({
          error: 'Invalid user ID',
          message: 'User ID must be a positive integer'
        });
      }

      // Security: Rate limit sensitive requests
      // In production, you might add additional checks here

      // Sample data lookup
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'Not found',
          message: 'User not found'
        });
      }

      res.json({
        data: user
      });

    } catch (error) {
      console.error('Error in /users/:id endpoint:', error);
      res.status(500).json({
        error: 'Internal server error',
        message: 'An error occurred while retrieving user'
      });
    }
  }
);

// ============================================================================
// GLOBAL ERROR HANDLING
// ============================================================================

/**
 * 404 Not Found Handler
 * Must be defined after all routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

/**
 * Global Error Handler
 * Catches all unhandled errors
 * In production, you might want to integrate with an error tracking service
 */
app.use((err, req, res, next) => {
  // Log error for debugging
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Security headers enabled`);
  console.log(`Rate limiting enabled`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

