  logSecurityEvent('error', 'Unhandled error', req, { 
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'Internal server error',
    code: 'INTERNAL_ERROR',
  };

  res.status(statusCode).json(response);
});
```

**Benefits:**
- Catches all unhandled errors
- Prevents stack trace leakage in production
- Provides consistent error responses

### 9. **Graceful Shutdown**
```javascript
const gracefulShutdown = (signal) => {
  console.log(`\nReceived ${signal}. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed. Process exiting.');
    process.exit(0);
  });

  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));
```

**Benefits:**
- Handles proper shutdown signals
- Closes connections gracefully
- Time-bound shutdown to prevent hanging

### 10. **Uncaught Exception Handlers**
```javascript
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});
```

**Benefits:**
- Prevents server crash from unhandled exceptions
- Logs unhandled promise rejections
- Cleans up resources before exit

### 11. **404 Handler**
```javascript
app.use((req, res) => {
  logSecurityEvent('warn', '404 Not Found', req);
  res.status(404).json({ 
    error: 'Resource not found',
    code: 'NOT_FOUND',
    path: req.path
  });
});
```

**Benefits:**
- Catches requests to non-existent routes
- Logs potential probing attacks
- Returns consistent error messages

## Additional Security Recommendations

### 1. **Dependencies Required**
Install additional security packages:
```bash
npm install helmet express-rate-limit cors
```

### 2. **Environment Variables**
Create a `.env` file:
```env
NODE_ENV=production
ALLOWED_ORIGINS=http://localhost:3000,https://yourdomain.com
```

### 3. **Authentication**
Add authentication middleware for protected routes:
```javascript
const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
};
```

### 4. **HTTPS Enforcement**
Add HTTPS enforcement in production:
```javascript
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure) {
      return res.redirect(`https://${req.headers.host}${req.url}`);
    }
    next();
  });
}
```

### 5. **Input Validation Library**
Consider using `joi` or `express-validator` for more complex validation:
```bash
npm install joi
```

### 6. **Security Headers Testing**
Use tools to verify security headers:
```bash
npx @lhci/cli autorun
# or
curl -I https://yourapp.com/health
```

### 7. **Regular Security Audits**
Run regular dependency audits:
```bash
npm audit
npm audit fix
```

## Testing the Improvements

