const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Stricter rate limiting for user-related endpoints
const userLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30,
  message: 'Too many user requests from this IP, please try again later.',
});

// Validation middleware to handle validation errors
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Input sanitization helper
const sanitizeOutput = (data) => {
  if (typeof data !== 'object' || data === null) {
    return data;
  }

  const sanitized = Array.isArray(data) ? [] : {};

  for (const key in data) {
    if (data.hasOwnProperty(key)) {
      // Remove potentially dangerous keys if they exist
      if (['__proto__', 'constructor', 'prototype'].includes(key)) {
        continue;
      }
      sanitized[key] = sanitizeOutput(data[key]);
    }
  }

  return sanitized;
};

// Health check endpoint with request ID tracking
app.get('/health', asyncHandler(async (req, res) => {
  // Generate request ID for tracking
  req.id = req.id || require('crypto').randomBytes(16).toString('hex');

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    requestId: req.id,
  });
}));

// Users endpoint with validation and security
app.get(
  '/users',
  userLimiter,
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
    query('fields')
      .optional()
      .matches(/^[a-zA-Z0-9,_]+$/)
      .withMessage('Fields must contain only alphanumeric characters, commas, and underscores'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { limit = 10, offset = 0, fields } = req.query;

    // Simulated user data - in production, fetch from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + parseInt(limit));

    // Filter fields if specified
    let result = paginatedUsers;
    if (fields) {
      const requestedFields = fields.split(',');
      result = paginatedUsers.map(user => {
        const filteredUser = {};
        requestedFields.forEach(field => {
          if (user.hasOwnProperty(field)) {
            filteredUser[field] = user[field];
          }
        });
        return filteredUser;
      });
    }

    // Sanitize output to prevent prototype pollution
    const sanitizedResult = sanitizeOutput(result);

    res.json({
      data: sanitizedResult,
      meta: {
        total: users.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
        count: sanitizedResult.length,
      },
    });
  })
);

// Get specific user by ID
app.get(
  '/users/:id',
  userLimiter,
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const userId = parseInt(req.params.id);

