const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent DoS attacks and brute force
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later'
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
  trustProxy: true // Trust X-Forwarded-* headers if behind a reverse proxy
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const sensitiveLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 requests per 15 minutes
  skipSuccessfulRequests: false
});

// Configure body parsing with size limits to prevent payload attacks
app.use(express.json({ 
  limit: '1mb', // Limit request body size
  strict: true // Only accept objects and arrays
}));

// Prevent parameter pollution
app.use(express.urlencoded({ 
  extended: true, 
  limit: '1mb',
  parameterLimit: 100 
}));

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to handle validation errors
 * Returns 400 Bad Request with detailed error messages
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Sanitize error messages to prevent information leakage
    const sanitizedErrors = errors.array().map(err => ({
      field: err.path || err.param,
      message: err.msg
    }));

    return res.status(400).json({
      error: 'Validation failed',
      details: sanitizedErrors
    });
  }
  next();
};

/**
 * Middleware to validate query parameters for user listing
 */
const validateUserQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  query('sort')
    .optional()
    .isIn(['id', 'name', 'email', '-id', '-name', '-email'])
    .withMessage('Sort must be a valid field'),
  query('search')
    .optional()
    .trim()
    .isLength({ max: 100 })
    .withMessage('Search term must be 100 characters or less')
    .escape(), // Prevent XSS in search terms
  handleValidationErrors
];

/**
 * Middleware to check if request is from trusted origin
 * Configure based on your application's needs
 */
const checkOrigin = (req, res, next) => {
  const origin = req.headers.origin;
  const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

  if (origin && !allowedOrigins.includes(origin)) {
    return res.status(403).json({ 
      error: 'Forbidden',
      message: 'Origin not allowed'
    });
  }

  next();
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Global error handler - should be the last middleware
 * Prevents stack trace leakage in production
 */
const errorHandler = (err, req, res, next) => {
  // Log the error for debugging (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Prepare error response - don't leak sensitive information in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: err.name || 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
};

/**
 * 404 Not Found handler
 */
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
};

/**
 * Async route wrapper to handle async errors
 * Wraps route handlers to catch rejected promises
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// REQUEST LOGGING
// ============================================================================

/**
 * Request logging middleware
 * Logs important request information for security monitoring
 */
app.use((req, res, next) => {
  const startTime = Date.now();

  // Log request details
  console.log({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString()
  });

  // Log response after it's sent
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log({
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      timestamp: new Date().toISOString()
    });
  });

  next();
});

// ============================================================================
// SECURITY HEADERS (Custom additions to helmet)
// ============================================================================

app.use((req, res, next) => {
  // Remove X-Powered-By header
  res.removeHeader('X-Powered-By');

  // Content Security Policy is set by helmet, but you can customize it
  // Example: res.setHeader('Content-Security-Policy', "default-src 'self'");

  // Prevent caching of sensitive data
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');

  next();
});

// ============================================================================
// CUSTOM VALIDATION HELPERS
// ============================================================================

/**
 * Validate and sanitize a string field
 */
const sanitizeString = (value, maxLength = 100) => {
  if (typeof value !== 'string') {
    throw new Error('Value must be a string');
  }
  const trimmed = value.trim();
  if (trimmed.length > maxLength) {
    throw new Error(`Value exceeds maximum length of ${maxLength}`);
  }
  // Prevent null byte injection
  if (trimmed.includes('\0')) {
    throw new Error('Invalid characters in value');
  }
  return trimmed;
};

/**
 * Validate ID parameter
 */
const validateId = (id) => {
  if (typeof id !== 'string' && typeof id !== 'number') {
    throw new Error('ID must be a string or number');
  }
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId < 1) {
    throw new Error('Invalid ID');
  }
  return numId;
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint with validation and sanitization
 */
app.get('/users', validateUserQuery, asyncHandler(async (req, res) => {
  try {
    // Get validated and sanitized query parameters
    const { limit = 10, offset = 0, sort = 'id', search } = req.query;

    // Mock user data (in production, fetch from database)
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    // Apply search filter if provided
    if (search) {
      const searchLower = search.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    // Apply sorting
    const [sortField, sortOrder] = sort.startsWith('-') 
      ? [sort.slice(1), -1] 
      : [sort, 1];

    paginatedUsers.sort((a, b) => {
      if (a[sortField] < b[sortField]) return -1 * sortOrder;
      if (a[sortField] > b[sortField]) return 1 * sortOrder;
      return 0;
    });

    // Return response with metadata
    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    // Log the error and re-throw for the error handler
    console.error('Error fetching users:', error);
    error.statusCode = 500;
    throw error;
  }
}));

/**
 * Get user by ID endpoint
 */
app.get('/users/:id', [
  // Validate ID parameter
  body('id')
    .custom((value) => {
      validateId(value);
      return true;
    })
], handleValidationErrors, asyncHandler(async (req, res, next) => {
  try {
    const id = validateId(req.params.id);

    // Mock user lookup (in production, fetch from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      const error = new Error('User not found');
      error.statusCode = 404;
      throw error;
    }

    res.json(user);
  } catch (error) {
    if (!error.statusCode) {
      error.statusCode = 500;
    }
    throw error;
  }
}));

/**
 * Create user endpoint with validation
 */
app.post('/users', [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z0-9\s\-']+$/)
    .withMessage('Name contains invalid characters')
    .escape(),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail()
    .isLength({ max: 255 })
    .withMessage('Email exceeds maximum length'),
  handleValidationErrors
], sensitiveLimiter, asyncHandler(async (req, res) => {
  try {
    const { name, email } = req.body;

    // In production, save to database with proper input sanitization
    // This is a mock example - always use parameterized queries or an ORM
    const newUser = {
      id: Date.now(), // This is just for demo - use proper IDs in production
      name: sanitizeString(name),
      email: email.toLowerCase()
    };

    res.status(201).json(newUser);
  } catch (error) {
    error.statusCode = 500;
    throw error;
  }
}));

// ============================================================================
// 404 AND ERROR HANDLERS (Must be last)
// ============================================================================

// Handle 404s for undefined routes
app.use(notFoundHandler);

// Global error handler (must be last)
app.use(errorHandler);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// ============================================================================
// GRACEFUL SHUTDOWN HANDLING
// ============================================================================

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

// Handle shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

