// Implements security best practices for production use

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware configuration
app.use(helmet()); // Sets various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size to prevent DoS
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent DDoS and brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many requests on sensitive endpoint' },
});

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation
app.get(
  '/users',
  [
    // Validate and sanitize query parameters
    query('id')
      .optional()
      .isInt({ min: 1, max: 999999 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('name')
      .optional()
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape(), // Sanitize to prevent XSS
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
  ],
  validateRequest,
  (req, res) => {
    try {
      // Mock user data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      let filteredUsers = users;

      // Apply ID filter if provided
      if (req.query.id !== undefined) {
        filteredUsers = filteredUsers.filter(u => u.id === req.query.id);
      }

      // Apply name filter if provided (case-insensitive, partial match)
      if (req.query.name) {
        const searchTerm = req.query.name.toLowerCase();
        filteredUsers = filteredUsers.filter(u =>
          u.name.toLowerCase().includes(searchTerm)
        );
      }

      // Apply sort if provided
      if (req.query.sort) {
        filteredUsers.sort((a, b) =>
          a[req.query.sort] > b[req.query.sort] ? 1 : -1
        );
      }

      // Apply limit if provided
      if (req.query.limit) {
        filteredUsers = filteredUsers.slice(0, req.query.limit);
      }

      // Don't expose internal IDs in responses if not necessary
      const response = filteredUsers.map(({ id, name, email }) => ({
        id,
        name,
        email: email.includes('@') ? email : '***@***.***', // Basic email masking
      }));

      res.json({
        success: true,
        count: response.length,
        data: response,
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        success: false,
        error: 'An error occurred while fetching users',
      });
    }
  }
);

// Example user creation endpoint with validation
app.post(
  '/users',
  strictLimiter, // Stricter rate limiting for write operations
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters')
      .escape(),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Must be a valid email address')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email too long'),
    body('age')
      .optional()
      .isInt({ min: 0, max: 150 })
      .withMessage('Age must be between 0 and 150'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const { name, email, age } = req.body;

      // In a real app, you would save to a database here
      console.log('Creating user:', { name, email, age });

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: {
          name,
          email: email.replace(/(?<=.{2}).(?=.*@)/g, '*'), // Mask email in response
          age,
        },
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({
        success: false,
        error: 'An error occurred while creating the user',
      });
    }
  }
);

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    success: false,
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

